const zlib = require('node:zlib');

// A verified snapshot of the currently released gacha operators. It lets a
// fresh installation resolve existing operators without first contacting a
// third-party game-data mirror. Newer operators remain dynamically supported
// by the network/cache path in main.js.
const COMPRESSED_MAP = '';

function getBundledOperatorIdMap() {
  const source = zlib.gunzipSync(Buffer.from(COMPRESSED_MAP, 'base64')).toString('utf8');
  return new Map(Object.entries(JSON.parse(source)));
}

module.exports = { getBundledOperatorIdMap };
